            children: vec![
                UiNode { node_id: UiNodeId("a".into()), kind: UiNodeKind::Button, bounds: UiBounds { x: 0.0, y: 0.0, width: 20.0, height: 10.0 }, layout: Some(UiLayout { margin: [1.0, 2.0, 3.0, 4.0], ..UiLayout::default() }), visible: true, enabled: true, text_key: None, text: None, image: None, surface: None, style: UiStyle::default(), enter_transition: None, children: Vec::new() },
                UiNode { node_id: UiNodeId("b".into()), kind: UiNodeKind::Button, bounds: UiBounds { x: 0.0, y: 0.0, width: 20.0, height: 10.0 }, layout: None, visible: true, enabled: true, text_key: None, text: None, image: None, surface: None, style: UiStyle::default(), enter_transition: None, children: Vec::new() },
            ],
        }
    }

    #[test]
    fn row_column_dpi_and_scroll_layout_are_deterministic() {
        let row = resolve_layout(&layout_node(UiLayoutMode::Row), UiBounds { x: 0.0, y: 0.0, width: 0.0, height: 0.0 }, 2.0).unwrap();
        assert_eq!(row[1], UiBounds { x: 16.0, y: 10.0, width: 40.0, height: 20.0 });
        assert_eq!(row[2].x, 58.0);
        let column = resolve_layout(&layout_node(UiLayoutMode::Column), UiBounds { x: 0.0, y: 0.0, width: 0.0, height: 0.0 }, 1.0).unwrap();
        assert_eq!(column[1].y, 5.0);
        assert_eq!(column[2].y, 20.0);
        let mut scrolled = layout_node(UiLayoutMode::Column);
        scrolled.layout.as_mut().unwrap().scroll_offset = [0.0, 2.0];
        assert_eq!(resolve_layout(&scrolled, UiBounds { x: 0.0, y: 0.0, width: 0.0, height: 0.0 }, 1.0).unwrap()[1].y, 3.0);
    }

    #[test]
    fn layout_clamps_sizes_and_rejects_invalid_values() {
        let mut node = layout_node(UiLayoutMode::Absolute);
        node.layout.as_mut().unwrap().min_size = Some([120.0, 70.0]);
        node.layout.as_mut().unwrap().max_size = Some([130.0, 80.0]);
        assert_eq!(resolve_layout(&node, UiBounds { x: 0.0, y: 0.0, width: 0.0, height: 0.0 }, 1.0).unwrap()[0].width, 120.0);
        node.layout.as_mut().unwrap().gap = -1.0;
        assert_eq!(resolve_layout(&node, UiBounds { x: 0.0, y: 0.0, width: 0.0, height: 0.0 }, 1.0), Err(UiSchemaError::InvalidLayout));
    }

    #[test]
    fn duplicate_sibling_node_identity_is_rejected_as_layout_error() {
        let mut node = layout_node(UiLayoutMode::Overlay);
        node.children[1].node_id = node.children[0].node_id.clone();
        assert_eq!(node.validate(), Err(UiSchemaError::DuplicateNodeId));
    }

    #[test]
    fn image_nodes_require_a_stable_asset_ref_without_a_path() {
        let mut node = layout_node(UiLayoutMode::Absolute);
        node.kind = UiNodeKind::Image;
        assert_eq!(node.validate(), Err(UiSchemaError::MissingImageAsset));
        node.image = Some(AssetRef {
            project_id: "fixture-project".into(),
            asset_id: 81,
            revision: Revision(5),
            kind: "image".into(),
        });
        node.validate().unwrap();
        let value = serde_json::to_value(node).unwrap();
        assert!(value["image"].get("path").is_none());
        assert_eq!(value["image"]["asset_id"], 81);
    }

    #[test]
    fn render_surface_nodes_require_an_opaque_runtime_target() {
        let mut node = layout_node(UiLayoutMode::Absolute);
        node.kind = UiNodeKind::RenderSurface;
        assert_eq!(node.validate(), Err(UiSchemaError::MissingRenderSurfaceRef));
        node.surface = Some(RenderSurfaceRef { target_id: " ".into() });
        assert_eq!(node.validate(), Err(UiSchemaError::InvalidRenderSurfaceRef));
        node.surface = Some(RenderSurfaceRef { target_id: "ai.terrain.preview".into() });
        node.validate().unwrap();
        let value = serde_json::to_value(node).unwrap();
        assert_eq!(value["kind"], "render_surface");
        assert_eq!(value["surface"]["target_id"], "ai.terrain.preview");
        for forbidden in ["wgpu", "texture", "handle", "project_id", "asset_id"] {
            assert!(value["surface"].get(forbidden).is_none());
        }
    }

    #[test]
    fn text_ref_is_source_independent_and_rejects_empty_content() {
        let mut node = layout_node(UiLayoutMode::Absolute);
        node.text = Some(TextRef::Key { key: "ui.fixture.label".into(), arguments: serde_json::json!({"count": 2}) });
        node.validate().unwrap();
        let encoded = serde_json::to_value(&node).unwrap().to_string();
        for forbidden in ["path", "font_file", "wgpu", "handle"] {
            assert!(!encoded.contains(forbidden), "text declaration contains {forbidden}");
        }
        node.text = Some(TextRef::Literal { value: String::new() });
        assert_eq!(node.validate(), Err(UiSchemaError::InvalidText));
    }
}

//! Headless UI declaration runtime. It must not create windows or GPU objects.

use std::{collections::HashMap, net::SocketAddr};

use neon_ipc::{RpcClient, RpcServer, TransportError};
use neon_observability::{
    CommandJournal, CommandReceipt, CommandState, DebugSnapshot, EVENT_COMMAND_ACCEPTED,
    EVENT_COMMAND_RECEIVED, EVENT_COMMAND_REJECTED, JournalFilter, TraceLevel, TraceRecord,
};
use neon_protocol::{
    AiTerrainCondition, ClientIdentity, ClientKind, HealthStatus, PROTOCOL_VERSION, ProtocolVersion, RequestId,
    Revision, RpcError, RpcRequest, RpcResponse, RpcStatus, ServiceDescription, ServiceHealth, ServiceName,
};
use neon_ui_schema::{
    UiBounds, UiCommand, UiEffect, UiFragment, UiFragmentId, UiFragmentSubmission, UiNode, UiNodeId, UiNodeKind, UiStyle,
    UiDiagnosticsState, UiInspectorState, UiInspectorTab, UiSurfaceEvent, UiSurfaceEventKind, UiSurfaceEventRequest, UiSurfaceId, UiSurfaceSnapshot, UiSurfaceState, UI_SURFACE_SCHEMA_VERSION,
    UiSemanticEvent, UiTransition, UiTransitionState, ERROR_FRAGMENT_REVISION_STALE,
    ERROR_INPUT_SEQUENCE_STALE, ERROR_INTENT_NOT_BOUND, ERROR_RENDERER_EPOCH_MISMATCH,
};
use serde_json::{Value, json};

pub const SERVICE_NAME: &str = "ui-runtime";
pub const WORKBENCH_SURFACE_ID: &str = "surface.ui-workbench";
pub const AI_TERRAIN_SURFACE_ID: &str = "surface.ai.terrain-generator";

#[derive(Clone, Debug, PartialEq)]
struct AiTerrainPanelState {
    revision: Revision,
    condition: AiTerrainCondition,
    guidance: f32,
    steps: u32,
    seed: u64,
    last_seed: Option<u64>,
    size: u32,
    target_id: String,
    state: String,
    job_id: Option<String>,
    elapsed_ms: Option<f64>,
    error_code: Option<String>,
}

impl Default for AiTerrainPanelState {
    fn default() -> Self {
        Self {
            revision: Revision(1),
            condition: AiTerrainCondition {
                sub: Some(6),
                parent: Some(1),
                relief: Some(3),
                texture: Some(2),
                water: Some(2),
            },
            guidance: 0.0,
            steps: 4,
            seed: 42,
            last_seed: None,
            size: 256,
            target_id: "ai.terrain.preview".into(),
            state: "idle".into(),
            job_id: None,
            elapsed_ms: None,
            error_code: None,
        }
    }
}

impl AiTerrainPanelState {
    fn snapshot(&self) -> Value {
        json!({
            "schema_version": 1,
            "surface_id": AI_TERRAIN_SURFACE_ID,
            "revision": self.revision,
            "condition": self.condition,
            "guidance": self.guidance,
            "steps": self.steps,
            "seed": self.seed,
            "last_seed": self.last_seed,
            "size": self.size,
