    }
}

impl UiIntent {
    pub fn validate(&self) -> Result<(), UiSchemaError> {
        match self {
            Self::Invoke { action, .. } if action.trim().is_empty() => Err(UiSchemaError::EmptyAction),
            Self::Invoke { .. } => Ok(()),
        }
    }
}

impl TextRef {
    fn is_valid(&self) -> bool {
        match self {
            Self::Key { key, .. } => !key.trim().is_empty(),
            Self::Literal { value } => !value.is_empty(),
        }
    }
}

