                        from: UiTransitionState {
                            opacity: Some(0.0),
                            ..UiTransitionState::default()
                        },
                    }),
                    children: Vec::new(),
                }],
            },
            effects: vec![
                UiEffect::SemanticAction { action: "ui.static.ready".into() },
                UiEffect::SemanticIntent { intent: neon_ui_schema::UiIntent::Invoke {
