    #[test]
    fn semantic_event_serialization_has_no_renderer_local_or_coordinate_data() {
        let event = UiSemanticEvent {
            event: UiSemanticEventType::PointerClick,
            event_id: "event-1".into(),
            renderer_epoch: 7,
            composition_revision: Revision(3),
